import {calendar,courses,schedules,sources} from './data.js?v=20261014f';
import {escapeHTML as e,thaiDate,today,addDays} from './core.js?v=20261014f';
import {calendarEvents,defaultMonth,activityMonth,firstLecture,lectureClashes,monthBounds,shiftMonth,weekdays,scheduleICS} from './calendar-core.js?v=20261014-study2';
let month=defaultMonth(),type='all',course='',view='month',selected='';
const monthName=m=>new Intl.DateTimeFormat('th-TH',{month:'long',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date(m+'-01T12:00:00+07:00'));
const sourceURL=id=>sources.find(s=>s.id===id)?.url||'#about';
const scheduleCopy=page=>'./sources/mr30-2-2569-p142-143.pdf'+(page?'#page='+Math.max(1,page-141):'');
function eventRow(x){
 if(x.type==='notice')return `<article class="calendar-event notice-event"><span class="event-type">งดบรรยาย</span><div><b>${e(x.title)}</b><p>${thaiDate(x.date)}</p></div></article>`;
 return `<article class="calendar-event ${x.type}-event"><div class="event-when"><span class="event-type">${x.type==='exam'?'สอบ':'เรียนตามตาราง'}</span><strong>${e(x.time)}</strong><span>${thaiDate(x.date,true)}</span></div><div class="event-body"><a href="#course/${x.course}"><b>${x.course}</b> ${e(x.title)}</a><p>${x.type==='exam'?'ชั่วโมงสอบและห้องสอบ: ตรวจตารางสอบรายบุคคล':`ห้องเรียน ${e(x.room)} · เวลาไทย (UTC+7)`}</p>${x.clash?'<span class="event-warning">เวลาเรียนชนกับอีกวิชา</span>':''}${x.check?`<p class="event-warning">${e(x.check)}</p>`:''}</div><a class="text-link event-source" href="${e(x.source==='mr30'?scheduleCopy(x.page):sourceURL(x.source))}" target="_blank" rel="noopener noreferrer">ม.ร.30 (สำเนา)${x.page?' น. '+x.page:''} ↗</a></article>`;
}
function agenda(events){
 if(!events.length)return '<div class="empty">ไม่มีรายการตามตัวกรองในช่วงนี้ ลองเลือกเดือนหรือวิชาอื่น</div>';
 let date='';return events.map(x=>{const heading=date!==x.date?`<h3 class="agenda-date">${weekdays[new Date(x.date+'T12:00:00Z').getUTCDay()]} ${thaiDate(x.date)}</h3>`:'';date=x.date;return heading+eventRow(x);}).join('');
}
function grid(events){
 const {start,end}=monthBounds(month),offset=(new Date(start+'T12:00:00Z').getUTCDay()+6)%7,cells=[];
 for(let i=0;i<offset;i++)cells.push('<div class="calendar-blank" aria-hidden="true"></div>');
 for(let date=start;date<=end;date=addDays(date,1)){
  const dayEvents=events.filter(x=>x.date===date),isToday=date===today();
  cells.push(`<button class="calendar-day ${isToday?'is-today':''} ${selected===date?'is-selected':''}" data-action="cal-day" data-date="${date}" aria-label="${e(thaiDate(date))} ${dayEvents.length} รายการ" aria-pressed="${selected===date}"><span class="calendar-day-number">${Number(date.slice(8))}${isToday?'<span class="sr-only"> วันนี้</span>':''}</span><span class="calendar-day-events">${dayEvents.map(x=>`<span class="calendar-chip ${x.type}" title="${e(x.type==='notice'?x.title:x.time+' '+x.title)}">${x.type==='notice'?'งดเรียน':`${x.type==='exam'?'สอบ':'เรียน'} <span class="calendar-chip-code"><span>${x.course.slice(0,3)}</span><span>${x.course.slice(3)}</span></span>`}<small>${x.type==='notice'?'':e(x.time)}</small>${x.clash?'<span class="chip-warning">ชน</span>':''}</span>`).join('')}</span></button>`);
 }
 while(cells.length%7)cells.push('<div class="calendar-blank" aria-hidden="true"></div>');
 return `<div class="calendar-grid" aria-label="ปฏิทิน ${e(monthName(month))}">${['จ.','อ.','พ.','พฤ.','ศ.','ส.','อา.'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells.join('')}</div><div class="calendar-selected" aria-live="polite"><h2>${selected?'รายการวันที่ '+thaiDate(selected):'แตะวันที่เพื่อดูเวลาและห้องเรียน'}</h2>${selected?agenda(events.filter(x=>x.date===selected)):'<p>สีฟ้า = เรียน · สีแดง = สอบ · สีเหลือง = งดบรรยาย มีข้อความกำกับทุกสี</p>'}</div>`;
}
export function lectureInfo(code){const s=schedules.find(x=>x.course===code);if(!s)return '';return `<div class="notice lecture-info"><strong>ตารางเรียน: วัน${weekdays[s.weekday]} ${s.startTime}–${s.endTime} น. · ห้อง ${e(s.room)}</strong><p>รอบแรกตามตาราง ${thaiDate(firstLecture(s))} · ${lectureClashes().some(p=>p.some(x=>x.course===code))?'เวลาเรียนตรงกับอีกวิชาที่ลงไว้ · ':''}<a href="#calendar">ดูปฏิทินเรียน–สอบและประกาศงดบรรยาย →</a></p></div>`;}
export function calendarPage(){
 const bounds=monthBounds(month),events=calendarEvents({...bounds,type,course}),allExams=calendarEvents({type:'exam'}),clashes=lectureClashes();
 return `<div class="page-heading"><div><div class="eyebrow">CLASS & EXAM CALENDAR · 2/2569</div><h1>ปฏิทินเรียนและสอบ</h1><p>วัน เวลา และห้องเรียนของ 7 วิชา · ตาม ม.ร.30 ส่วนกลาง · เวลาไทย</p></div><a class="button secondary" href="#exams">แนวข้อสอบ 7 วิชา →</a></div>
 <div class="calendar-facts"><div><span>เริ่มช่วงบรรยาย</span><b>${thaiDate(calendar.lectureStart,true)}</b></div><div><span>สิ้นสุดช่วงบรรยาย</span><b>${thaiDate(calendar.lectureEnd,true)}</b></div><div><span>สอบวิชาที่ลงไว้</span><b>${thaiDate(allExams[0].date,true)} – ${thaiDate(allExams.at(-1).date,true)}</b></div></div>
 <div class="calendar-alert"><strong>มีเวลาเรียนชนกัน ${clashes.length} คู่</strong>${clashes.map(([a,b])=>`<p><b>${a.course} + ${b.course}</b> · วัน${weekdays[a.weekday]} ${a.startTime}–${a.endTime} น. (${e(a.room)} / ${e(b.room)})</p>`).join('')}<p>วันสอบทั้ง 7 วิชาไม่ชนกัน เวลาที่ชนนี้คือการบรรยาย เลือกสดหนึ่งวิชา–ย้อนหลังอีกวิชาได้เมื่อมีคลิป และตรวจเงื่อนไขกิจกรรมจากผู้สอน</p><div class="button-row"><a class="button secondary" href="${e(sourceURL('live'))}" target="_blank" rel="noopener noreferrer">● เรียนสด</a><a class="button secondary" href="${e(sourceURL('video'))}" target="_blank" rel="noopener noreferrer">▶ ดูย้อนหลัง</a><a class="text-link" href="#resources">วิธีจัดการวิชาชนกัน →</a></div></div>
 <section class="panel calendar-panel"><div class="calendar-toolbar"><div class="segmented" aria-label="ประเภทกิจกรรม">${[['all','ทั้งหมด'],['lecture','เรียน'],['exam','สอบ']].map(([key,label])=>`<button data-action="cal-filter" data-type="${key}" aria-pressed="${type===key}" class="${type===key?'active':''}">${label}</button>`).join('')}</div><label class="calendar-course">รายวิชา<select id="calendar-course"><option value="">ทุกวิชา</option>${courses.filter(c=>c.enrolled).map(c=>`<option value="${c.id}" ${course===c.id?'selected':''}>${c.id} · ${e(c.title)}</option>`).join('')}</select></label><div class="segmented" aria-label="รูปแบบปฏิทิน">${[['month','รายเดือน'],['list','รายการ']].map(([key,label])=>`<button data-action="cal-view" data-view="${key}" class="${view===key?'active':''}" aria-pressed="${view===key}">${label}</button>`).join('')}</div></div>
 <div class="calendar-month-nav"><button class="button secondary small" data-action="cal-month" data-delta="-1" aria-label="เดือนก่อนหน้า">←</button><h2 aria-live="polite">${e(monthName(month))}</h2><button class="button secondary small" data-action="cal-month" data-delta="1" aria-label="เดือนถัดไป">→</button><div class="calendar-jumps"><button class="button secondary small" data-action="cal-jump" data-month="${today().slice(0,7)}">เดือนนี้</button><button class="button secondary small" data-action="cal-jump" data-type="lecture" data-month="${calendar.lectureStart.slice(0,7)}">เริ่มเรียน</button><button class="button secondary small" data-action="cal-jump" data-type="exam" data-month="${calendar.examStart.slice(0,7)}">เดือนสอบ</button></div></div>
 ${view==='month'?grid(events):`<div class="calendar-agenda" aria-live="polite">${agenda(events)}</div>`}
 <div class="calendar-export"><button class="button primary" data-action="cal-export">ดาวน์โหลดปฏิทินทั้งเทอม (.ics)</button><p>ส่งออกตามตัวกรองวิชาและประเภท · เรียนมีเวลาไทย · สอบเป็นกิจกรรมทั้งวันพร้อมคาบ A/B</p></div></section>
 <details class="panel weekly-schedule"><summary>ตารางเรียนประจำสัปดาห์ครบ 7 วิชา</summary><div class="table-scroll"><table><thead><tr><th scope="col">วันเรียน</th><th scope="col">วิชา</th><th scope="col">เวลา</th><th scope="col">ห้องเรียน</th><th scope="col">รอบแรกตามตาราง</th></tr></thead><tbody>${[...schedules].sort((a,b)=>a.weekday-b.weekday||a.startTime.localeCompare(b.startTime)).map(s=>`<tr><td>${weekdays[s.weekday]}</td><td><a href="#course/${s.course}"><b>${s.course}</b></a>${clashes.some(p=>p.some(x=>x.course===s.course))?' <span class="event-warning">เวลาชน</span>':''}</td><td>${s.startTime}–${s.endTime}</td><td>${e(s.room)}</td><td>${thaiDate(firstLecture(s),true)}</td></tr>`).join('')}</tbody></table></div></details>
 <section class="panel calendar-sources"><h2>ตรวจตารางต้นฉบับได้ที่ไหน</h2><p><a href="${e(sourceURL('mr30'))}" target="_blank" rel="noopener noreferrer">เปิด ม.ร.30 ฉบับต้นฉบับที่มหาวิทยาลัย ↗</a> — รายวิชา วัน เวลา ห้องเรียน และวันสอบ</p><p><a class="button secondary" href="./sources/mr30-2-2569-p142-143.pdf" target="_blank" rel="noopener noreferrer">เปิดสำเนา ม.ร.30 เฉพาะหน้า 142–143 ↗</a></p><p>สำเนาสองหน้าคัดจากไฟล์ของมหาวิทยาลัยโดยไม่แก้ข้อมูล เก็บไว้เมื่อ 14 ต.ค. 2569 เพื่อเปิดได้แม้เว็บต้นฉบับขัดข้อง ปุ่มอ้างอิงข้างแต่ละวิชาเปิดสำเนานี้แล้ว</p><p><a href="${e(sourceURL('academic-calendar'))}" target="_blank" rel="noopener noreferrer">เปิดปฏิทินการศึกษาส่วนกลาง ↗</a> — ช่วงบรรยายและประกาศงดบรรยาย</p><p>ตรวจข้อมูลเมื่อ ${thaiDate(calendar.verified)} · 20 ม.ค. 2570 งดบรรยายเตรียมสอบซ่อม ส่วน 21–26 ม.ค. เป็นช่วงสอบซ่อม ภาค 1/2569 จึงทำเครื่องหมายให้ตรวจประกาศการบรรยายอีกครั้ง</p><p><b>${e(calendar.note)}</b> ห้องที่แสดงเป็นห้องเรียน ไม่ใช่ห้องสอบ วันเวลาของภาคต่อไปต้องใช้ ม.ร.30 ฉบับใหม่</p></section>`;
}
export function calendarAction(action,data){
 if(action==='cal-filter'&&['all','lecture','exam'].includes(data.type)){type=data.type;selected='';month=activityMonth(type,today(),course);}
 else if(action==='cal-view'&&['month','list'].includes(data.view))view=data.view;
 else if(action==='cal-month'&&[-1,1].includes(Number(data.delta))){month=shiftMonth(month,Number(data.delta));selected='';}
 else if(action==='cal-day'&&/^\d{4}-\d{2}-\d{2}$/.test(data.date))selected=data.date;
 else if(action==='cal-jump'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(data.month)){month=data.month;selected='';if(['all','lecture','exam'].includes(data.type))type=data.type;}
 else return false;
 return true;
}
export function calendarCourse(value){if(value===''||courses.some(c=>c.enrolled&&c.id===value)){course=value;selected='';month=activityMonth(type,today(),course);}}
export function calendarDownload(){return scheduleICS({type,course});}
